import { tv } from "tailwind-variants";

const tooltip = tv({
  slots: {
    trigger: "",
    portal: "",
    positioner: "",
    popup: [
      "relative flex origin-(--transform-origin) flex-col rounded-md border border-border bg-popover px-2 py-1.5 text-sm leading-none text-popover-foreground shadow-md transition-[scale,opacity] duration-200 ease-default",
      "data-ending-style:scale-95 data-ending-style:opacity-0",
      "data-instant:transition-none",
      "data-starting-style:scale-95 data-starting-style:opacity-0",
    ],
    arrow: [
      "relative block h-1.5 w-3 overflow-clip",
      "before:absolute before:bottom-0 before:left-1/2 before:h-[calc(6px*sqrt(2))] before:w-[calc(6px*sqrt(2))] before:transform-[translate(-50%,50%)_rotate(45deg)] before:border before:border-border before:bg-popover before:content-['']",
      "data-[side=bottom]:-top-1.5",
      "data-[side=inline-end]:-inset-s-2.25 data-[side=inline-end]:-rotate-90",
      "data-[side=inline-start]:-inset-e-2.25 data-[side=inline-start]:rotate-90",
      "data-[side=left]:-right-2.25 data-[side=left]:rotate-90",
      "data-[side=right]:-left-2.25 data-[side=right]:-rotate-90",
      "data-[side=top]:-bottom-1.5 data-[side=top]:rotate-180",
    ],
    viewport: "",
  },
});

export { tooltip };

"use client";

import { Tooltip as BaseTooltip } from "@base-ui/react/tooltip";

import { mergeSlotClassName } from "@/registry/sector23/lib/merge-base-ui";

import { tooltip } from "./tooltip.style";

const POSITIONER_SIDE_OFFSET = 6;

const createTooltipHandle = BaseTooltip.createHandle;

function TooltipProvider(props: BaseTooltip.Provider.Props) {
  return <BaseTooltip.Provider {...props} />;
}

function Tooltip(props: BaseTooltip.Root.Props) {
  return <BaseTooltip.Root {...props} />;
}

function TooltipTrigger({ className, ...props }: BaseTooltip.Trigger.Props) {
  return (
    <BaseTooltip.Trigger
      data-slot="tooltip-trigger"
      className={mergeSlotClassName(tooltip().trigger, className)}
      {...props}
    />
  );
}

function TooltipPortal({ className, ...props }: BaseTooltip.Portal.Props) {
  return (
    <BaseTooltip.Portal
      data-slot="tooltip-portal"
      className={mergeSlotClassName(tooltip().portal, className)}
      {...props}
    />
  );
}

function TooltipPositioner({
  className,
  sideOffset = POSITIONER_SIDE_OFFSET,
  ...props
}: BaseTooltip.Positioner.Props) {
  return (
    <BaseTooltip.Positioner
      data-slot="tooltip-positioner"
      className={mergeSlotClassName(tooltip().positioner, className)}
      sideOffset={sideOffset}
      {...props}
    />
  );
}

function TooltipPopup({ className, ...props }: BaseTooltip.Popup.Props) {
  return (
    <BaseTooltip.Popup
      data-slot="tooltip-popup"
      className={mergeSlotClassName(tooltip().popup, className)}
      {...props}
    />
  );
}

function TooltipArrow({ className, ...props }: BaseTooltip.Arrow.Props) {
  return (
    <BaseTooltip.Arrow
      data-slot="tooltip-arrow"
      className={mergeSlotClassName(tooltip().arrow, className)}
      {...props}
    />
  );
}

function TooltipViewport({ className, ...props }: BaseTooltip.Viewport.Props) {
  return (
    <BaseTooltip.Viewport
      data-slot="tooltip-viewport"
      className={mergeSlotClassName(tooltip().viewport, className)}
      {...props}
    />
  );
}

export {
  createTooltipHandle,
  TooltipProvider,
  Tooltip,
  TooltipTrigger,
  TooltipPortal,
  TooltipPositioner,
  TooltipPopup,
  TooltipArrow,
  TooltipViewport,
};
